def normalize_plaintext_bytes(value: str | bytes) -> bytes:
    if isinstance(value, bytes):
        return value
    return value.encode("utf-8")


def normalize_ciphertext_bytes(value: str | bytes) -> bytes:
    if isinstance(value, bytes):
        return value
    try:
        return base64.b64decode(value.encode("utf-8"))
    except Exception:
        return value.encode("utf-8")


